#include "openconsole/uefi_game_storage.h"
static const EFI_GUID info_guid={0x09576e92u,0x6d3fu,0x11d2u,{0x8e,0x39,0x00,0xa0,0xc9,0x69,0x72,0x3b}};
static const EFI_GUID fs_info_guid={0x09576e93u,0x6d3fu,0x11d2u,{0x8e,0x39,0x00,0xa0,0xc9,0x69,0x72,0x3b}};
typedef struct {uint64_t size;uint8_t read_only;uint8_t pad[7];uint64_t volume_size;uint64_t free_space;uint32_t block_size;CHAR16 volume_label[1];} oc_file_system_info;
static void zero(void*p,size_t n){uint8_t*b=p;while(n--)*b++=0;}
static int same(const char*a,const char*b){while(*a&&*a==*b){a++;b++;}return *a==*b;}
static int copy(char*out,size_t cap,const char*in){size_t n=0;while(in[n]){if(n+1>=cap)return 0;out[n]=in[n];n++;}out[n]=0;return 1;}
static void copy_bytes_local(void*out,const void*in,size_t n){uint8_t*d=out;const uint8_t*s=in;while(n--)*d++=*s++;}
static int wide(const char*p,CHAR16*out,size_t cap){size_t i=0;while(p[i]){if(i+1>=cap||(uint8_t)p[i]>=0x80)return 0;out[i]=(CHAR16)(uint8_t)p[i];i++;}out[i]=0;return 1;}
static int confined(const char*p){static const char prefix[]="\\EFI\\OpenConsole\\State\\Games\\";size_t i=0;if(!p)return 0;while(prefix[i]){if(p[i]!=prefix[i])return 0;i++;}if(!p[i])return 0;for(;p[i];i++)if((uint8_t)p[i]<0x20||p[i]=='/')return 0;return 1;}
static int ensure_parents(oc_uefi_game_storage*s,CHAR16 path[OC_GAME_STORAGE_PATH_MAX]){size_t i;EFI_STATUS st;for(i=1;path[i];i++)if(path[i]=='\\'){EFI_FILE_PROTOCOL*d=0;CHAR16 saved=path[i];path[i]=0;st=s->root->open(s->root,&d,path,EFI_FILE_MODE_READ|EFI_FILE_MODE_WRITE,EFI_FILE_DIRECTORY);if(st==EFI_NOT_FOUND)st=s->root->open(s->root,&d,path,EFI_FILE_MODE_READ|EFI_FILE_MODE_WRITE|EFI_FILE_MODE_CREATE,EFI_FILE_DIRECTORY);path[i]=saved;if(EFI_ERROR(st)||!d)return 0;d->close(d);}return 1;}
static int write_file(void*ctx,const char*path,const uint8_t*data,size_t size){oc_uefi_game_storage*s=ctx;CHAR16 w[OC_GAME_STORAGE_PATH_MAX];EFI_FILE_PROTOCOL*old=0,*f=0;EFI_STATUS st;UINTN n=size;if(s->pending_file||!confined(path)||!wide(path,w,OC_GAME_STORAGE_PATH_MAX)||!copy(s->pending_path,sizeof(s->pending_path),path)||!ensure_parents(s,w))return 0;st=s->root->open(s->root,&old,w,EFI_FILE_MODE_READ|EFI_FILE_MODE_WRITE,0);if(!EFI_ERROR(st)){if(EFI_ERROR(old->delete_file(old)))return 0;}else if(st!=EFI_NOT_FOUND)return 0;st=s->root->open(s->root,&f,w,EFI_FILE_MODE_READ|EFI_FILE_MODE_WRITE|EFI_FILE_MODE_CREATE,0);if(EFI_ERROR(st)||!f)return 0;st=f->write(f,&n,data);if(EFI_ERROR(st)||n!=size){f->close(f);return 0;}s->pending_file=f;return 1;}
static int flush_file(void*ctx,const char*path){oc_uefi_game_storage*s=ctx;EFI_STATUS a,b;if(!s->pending_file||!same(path,s->pending_path))return 0;a=s->pending_file->flush(s->pending_file);b=s->pending_file->close(s->pending_file);s->pending_file=0;s->pending_path[0]=0;return !EFI_ERROR(a)&&!EFI_ERROR(b);}
static int read_file(void*ctx,const char*path,uint8_t*data,size_t cap,size_t*size){oc_uefi_game_storage*s=ctx;CHAR16 w[OC_GAME_STORAGE_PATH_MAX];EFI_FILE_PROTOCOL*f=0;UINTN n=cap;EFI_STATUS st;if(!confined(path)||!wide(path,w,OC_GAME_STORAGE_PATH_MAX)||!data||!size)return-1;st=s->root->open(s->root,&f,w,EFI_FILE_MODE_READ,0);if(st==EFI_NOT_FOUND)return 0;if(EFI_ERROR(st)||!f)return-1;st=f->read(f,&n,data);f->close(f);if(EFI_ERROR(st))return-1;*size=n;return 1;}
static int read_alloc(oc_uefi_game_storage*s,const char*path,uint64_t maximum,void**data,UINTN*size){CHAR16 w[OC_GAME_STORAGE_PATH_MAX];EFI_FILE_PROTOCOL*f=0;EFI_FILE_INFO*info=0;UINTN is=0,n;EFI_STATUS st;*data=0;*size=0;if(!confined(path)||!wide(path,w,OC_GAME_STORAGE_PATH_MAX))return 0;st=s->root->open(s->root,&f,w,EFI_FILE_MODE_READ,0);if(EFI_ERROR(st))return 0;st=f->get_info(f,&info_guid,&is,0);if(st!=EFI_BUFFER_TOO_SMALL||is<sizeof(*info))goto done;if(EFI_ERROR(s->boot_services->allocate_pool(EFI_LOADER_DATA,is,(void**)&info)))goto done;if(EFI_ERROR(f->get_info(f,&info_guid,&is,info))||info->file_size>maximum||info->file_size>(uint64_t)(~(UINTN)0))goto done;n=(UINTN)info->file_size;if(EFI_ERROR(s->boot_services->allocate_pool(EFI_LOADER_DATA,n?n:1u,data)))goto done;st=f->read(f,&n,*data);if(EFI_ERROR(st)||n!=(UINTN)info->file_size){s->boot_services->free_pool(*data);*data=0;goto done;}*size=n;st=EFI_SUCCESS;done:if(info)s->boot_services->free_pool(info);if(f)f->close(f);return !EFI_ERROR(st)&&*data!=0;}
static int digest_file(void*ctx,const char*path,uint64_t*size,uint8_t digest[32]){oc_uefi_game_storage*s=ctx;void*data=0;UINTN n=0;EFI_STATUS st;if(!size||!digest||!read_alloc(s,path,OC_GAME_BUNDLE_MAX,&data,&n))return 0;st=s->crypto->sha256(s->crypto,data,n,digest);s->boot_services->free_pool(data);if(EFI_ERROR(st))return 0;*size=n;return 1;}
static int delete_file(void*ctx,const char*path){oc_uefi_game_storage*s=ctx;CHAR16 w[OC_GAME_STORAGE_PATH_MAX];EFI_FILE_PROTOCOL*f=0;EFI_STATUS st;if(!confined(path)||!wide(path,w,OC_GAME_STORAGE_PATH_MAX))return 0;st=s->root->open(s->root,&f,w,EFI_FILE_MODE_READ|EFI_FILE_MODE_WRITE,0);if(st==EFI_NOT_FOUND)return 1;if(EFI_ERROR(st)||!f)return 0;return !EFI_ERROR(f->delete_file(f));}
static int dots(const CHAR16*n){return n[0]=='.'&&(n[1]==0||(n[1]=='.'&&n[2]==0));}
static EFI_STATUS clean_dir(oc_uefi_game_storage*s,EFI_FILE_PROTOCOL*d,size_t depth,size_t maximum,size_t*removed,int*empty){EFI_FILE_INFO*info=0;EFI_STATUS st=EFI_SUCCESS;if(depth>16)return EFI_SECURITY_VIOLATION;if(EFI_ERROR(s->boot_services->allocate_pool(EFI_LOADER_DATA,2048,(void**)&info)))return EFI_OUT_OF_RESOURCES;for(;;){UINTN n=2048;EFI_FILE_PROTOCOL*c=0;st=d->set_position(d,0);if(EFI_ERROR(st))break;do{n=2048;st=d->read(d,&n,info);if(EFI_ERROR(st)||n==0)break;}while(dots(info->file_name));if(EFI_ERROR(st))break;if(n==0){*empty=1;break;}*empty=0;if(*removed>=maximum)break;st=d->open(d,&c,info->file_name,EFI_FILE_MODE_READ|EFI_FILE_MODE_WRITE,0);if(EFI_ERROR(st))break;if(info->attribute&EFI_FILE_DIRECTORY){int child_empty=0;st=clean_dir(s,c,depth+1,maximum,removed,&child_empty);if(!EFI_ERROR(st)&&child_empty&&*removed<maximum){st=c->delete_file(c);if(!EFI_ERROR(st)){c=0;(*removed)++;}}}else{st=c->delete_file(c);if(!EFI_ERROR(st)){c=0;(*removed)++;}}if(c)c->close(c);if(EFI_ERROR(st))break;}s->boot_services->free_pool(info);return st==EFI_NOT_FOUND?EFI_SUCCESS:st;}
static int cleanup_slot(void*ctx,const char*path,size_t maximum,size_t*removed,int*complete){oc_uefi_game_storage*s=ctx;CHAR16 w[OC_GAME_STORAGE_PATH_MAX];EFI_FILE_PROTOCOL*d=0;EFI_STATUS st;int empty=0;if(!removed||!complete||!maximum||!confined(path)||!wide(path,w,OC_GAME_STORAGE_PATH_MAX))return 0;*removed=0;*complete=0;st=s->root->open(s->root,&d,w,EFI_FILE_MODE_READ|EFI_FILE_MODE_WRITE,0);if(st==EFI_NOT_FOUND){*complete=1;return 1;}if(EFI_ERROR(st)||!d)return 0;st=clean_dir(s,d,0,maximum,removed,&empty);if(!EFI_ERROR(st)&&empty&&*removed<maximum){st=d->delete_file(d);if(!EFI_ERROR(st)){d=0;(*removed)++;*complete=1;}}if(d)d->close(d);return !EFI_ERROR(st);}
static int edverify(void*ctx,const uint8_t k[57],const uint8_t*m,size_t n,const uint8_t sig[114]){oc_uefi_game_storage*s=ctx;return !EFI_ERROR(s->crypto->ed448_verify(s->crypto,k,m,n,sig));}
static int validate_slot(void*ctx,const char*bpath,const char*dpath,const oc_game_selection*sel){oc_uefi_game_storage*s=ctx;void*b=0,*descriptor=0,*work=0;UINTN bn=0,dn=0;oc_authenticated_game game;oc_ocg2_bundle parsed;size_t i;int ok=0;if(!read_alloc(s,bpath,OC_GAME_BUNDLE_MAX,&b,&bn)||bn!=sel->bundle_size||!read_alloc(s,dpath,OC_GAME_INVENTORY_MAX,&descriptor,&dn))goto done;if(EFI_ERROR(s->boot_services->allocate_pool(EFI_LOADER_DATA,OC_OCG2_SIGNATURE_WORKSPACE,&work)))goto done;if(oc_authenticated_game_bundle(b,bn,s->publisher_keys,edverify,s,work,OC_OCG2_SIGNATURE_WORKSPACE,&game)!=OC_AUTH_LOAD_OK||!same(game.manifest.id,sel->game_id)||!same(game.manifest.version,sel->version))goto done;for(i=0;i<32;i++)if(game.bundle_id[i]!=sel->bundle_id[i])goto done;if(oc_ocg2_parse(b,bn,&parsed)!=OC_OCG2_OK||dn!=242u+parsed.index_size)goto done;for(i=0;i<dn;i++)if(((uint8_t*)descriptor)[i]!=((uint8_t*)b)[i])goto done;{uint8_t hash[32];if(EFI_ERROR(s->crypto->sha256(s->crypto,descriptor,dn,hash)))goto done;for(i=0;i<32;i++)if(hash[i]!=sel->inventory_digest[i])goto done;}for(i=0;i<parsed.count;i++){oc_ocg2_entry e;char rel[241],ppath[OC_GAME_STORAGE_PATH_MAX];uint64_t fs;uint8_t hash[32];size_t j;if(oc_ocg2_entry_at(&parsed,(uint32_t)i,&e)!=OC_OCG2_OK||e.path_size>240)goto done;for(j=0;j<e.path_size;j++)rel[j]=(char)e.path[j];rel[e.path_size]=0;if(oc_game_package_path(sel->game_id,sel->slot,rel,ppath,sizeof(ppath))!=OC_GAME_STORAGE_OK||!digest_file(s,ppath,&fs,hash)||fs!=e.size)goto done;for(j=0;j<32;j++)if(hash[j]!=e.digest[j])goto done;}ok=1;done:if(work)s->boot_services->free_pool(work);if(descriptor)s->boot_services->free_pool(descriptor);if(b)s->boot_services->free_pool(b);return ok;}
static int available_bytes(void*ctx,uint64_t*out){oc_uefi_game_storage*s=ctx;oc_file_system_info*info=0;UINTN n=0;EFI_STATUS st;if(!out)return 0;st=s->root->get_info(s->root,&fs_info_guid,&n,0);if(st!=EFI_BUFFER_TOO_SMALL||n<sizeof(*info)||EFI_ERROR(s->boot_services->allocate_pool(EFI_LOADER_DATA,n,(void**)&info)))return 0;st=s->root->get_info(s->root,&fs_info_guid,&n,info);if(!EFI_ERROR(st))*out=info->free_space;s->boot_services->free_pool(info);return !EFI_ERROR(st);}
EFI_STATUS oc_uefi_game_storage_initialize(oc_uefi_game_storage*s,EFI_BOOT_SERVICES*bs,EFI_FILE_PROTOCOL*root,OC_CRYPTO_PROTOCOL*crypto,const oc_publisher_key_store*keys){if(!s||!bs||!root||!crypto||!crypto->sha256||!crypto->ed448_verify||!keys)return EFI_INVALID_PARAMETER;zero(s,sizeof(*s));s->boot_services=bs;s->root=root;s->crypto=crypto;s->publisher_keys=keys;s->operations.context=s;s->operations.write_file=write_file;s->operations.flush_file=flush_file;s->operations.read_file=read_file;s->operations.digest_file=digest_file;s->operations.delete_file=delete_file;s->operations.cleanup_slot=cleanup_slot;s->operations.validate_slot=validate_slot;s->operations.available_bytes=available_bytes;return EFI_SUCCESS;}
EFI_STATUS oc_uefi_game_storage_read_authenticated_image(oc_uefi_game_storage*s,const oc_game_selection*sel,void**image,UINTN*size){char path[OC_GAME_STORAGE_PATH_MAX];void*b=0,*work=0,*copybuf=0;UINTN bn=0;oc_authenticated_game game;size_t i;EFI_STATUS st=EFI_SECURITY_VIOLATION;if(!s||!sel||!image||!size||sel->tombstone)return EFI_INVALID_PARAMETER;*image=0;*size=0;if(oc_game_storage_path(sel->game_id,OC_GAME_PATH_BUNDLE,sel->slot,path,sizeof(path))!=OC_GAME_STORAGE_OK||!read_alloc(s,path,OC_GAME_BUNDLE_MAX,&b,&bn)||bn!=sel->bundle_size)goto done;if(EFI_ERROR(s->boot_services->allocate_pool(EFI_LOADER_DATA,OC_OCG2_SIGNATURE_WORKSPACE,&work)))goto done;if(oc_authenticated_game_bundle(b,bn,s->publisher_keys,edverify,s,work,OC_OCG2_SIGNATURE_WORKSPACE,&game)!=OC_AUTH_LOAD_OK||!same(game.manifest.id,sel->game_id)||!same(game.manifest.version,sel->version))goto done;for(i=0;i<32;i++)if(game.bundle_id[i]!=sel->bundle_id[i])goto done;if(game.image_size>(size_t)(~(UINTN)0)||EFI_ERROR(s->boot_services->allocate_pool(EFI_LOADER_DATA,(UINTN)game.image_size,&copybuf)))goto done;copy_bytes_local(copybuf,game.image,game.image_size);*image=copybuf;*size=(UINTN)game.image_size;copybuf=0;st=EFI_SUCCESS;done:if(copybuf)s->boot_services->free_pool(copybuf);if(work)s->boot_services->free_pool(work);if(b)s->boot_services->free_pool(b);return st;}
void oc_uefi_game_storage_shutdown(oc_uefi_game_storage*s){if(s&&s->pending_file){s->pending_file->close(s->pending_file);s->pending_file=0;}}
